def can_form_subsequence(S: str, T: str, N: int) -> int:
    def can(k):
        index = 0
        for char in T[:k]:
            index = f.find(char, index) + 1
            if index == 0:
                return False
        return True

    f = S * N
    k = len(T)
    while k > 0 and not can(k):
        k -= 1
    return k
